const data = {
  "self-employed income": {title:"Income documentation for a self-employed borrower",answer:"Self-employed borrower income is generally evaluated from the most recent federal tax returns and business documentation. The lender must analyze the stability and continuation of the income, including the business’s financial strength where required by the AUS or guide.",practical:"Use the AUS findings to confirm the documentation set. A declining income trend, recently established business, or material business loss may require further analysis.",meta:"2 supporting sections · searched in 0.9s"},
  "gift funds": {title:"Using gift funds for a down payment",answer:"Gift funds may be used toward a borrower’s down payment, closing costs, and reserves when the donor and transfer are documented under the applicable guide. The borrower’s minimum contribution rules can still apply depending on occupancy, property type, and LTV.",practical:"Document the donor relationship, the gift amount, and evidence of transfer. Check the transaction’s minimum borrower contribution separately.",meta:"2 supporting sections · searched in 0.7s"},
  "accessory dwelling": {title:"Properties with an accessory dwelling unit",answer:"An accessory dwelling unit may be acceptable when it complies with the applicable property eligibility and appraisal requirements. The appraiser must identify and analyze the ADU, and any rental income treatment must follow the agency’s specific rules.",practical:"Confirm zoning, legal status, highest-and-best-use conclusion, and how the appraiser handled contributory value before relying on projected income.",meta:"2 supporting sections · searched in 1.1s"}
};
const input=document.getElementById('question'), title=document.getElementById('answerTitle'), body=document.getElementById('answerBody'), meta=document.getElementById('resultMeta');
function answer(){const q=input.value.trim().toLowerCase();const found=Object.entries(data).find(([key])=>q.includes(key.split(' ')[0])||q.includes(key));const item=found?found[1]:{title:"Guideline research result",answer:"I found the strongest source support in the Fannie Mae Selling Guide and Freddie Mac Guide. Review the retrieved sections alongside your AUS findings and the loan’s full facts before making an underwriting decision.",practical:"Use the official source links at right to confirm the current effective language and identify any transaction-specific exceptions.",meta:"2 supporting sections · searched in 0.8s"};title.textContent=item.title;body.innerHTML=`<p>${item.answer}</p><div class="callout"><span>↗</span><p><strong>Practical read:</strong> ${item.practical}</p></div><p class="fine-print">This research summary is not an underwriting decision. Confirm the current guide and your AUS findings before approving a loan.</p>`;meta.textContent=item.meta;document.querySelector('.answer-panel').scrollIntoView({behavior:'smooth',block:'nearest'});}
document.getElementById('askButton').addEventListener('click',answer);input.addEventListener('keydown',e=>{if(e.key==='Enter')answer()});document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.question;answer()}));document.getElementById('newQuery').addEventListener('click',()=>{input.value='';input.focus()});document.getElementById('copyAnswer').addEventListener('click',async()=>{await navigator.clipboard.writeText(`${title.textContent}\n\n${body.innerText}`);document.getElementById('copyAnswer').textContent='✓ Copied'});
